package com.vivekmlresearch.deterministicuniverse;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import java.util.*;
public final class MainActivity extends Activity{
 final int bg=Color.rgb(5,10,20),panel=Color.rgb(14,25,43),cyan=Color.rgb(70,225,255),muted=Color.rgb(166,183,205),yellow=Color.rgb(255,231,74);LinearLayout body;Graph graph;UniverseView universe;Spinner algorithm;TextView status;int start=0,goal=12;boolean choosingStart=true;
 public void onCreate(Bundle b){super.onCreate(b);graph=Graph.demo();shell();showLab();}
 void shell(){LinearLayout root=col();root.setBackgroundColor(bg);TextView t=txt("DETERMINISTIC UNIVERSE  v2",21,cyan,true);t.setPadding(d(16),d(14),d(16),d(2));root.addView(t);root.addView(txt("Interactive algorithm laboratory",13,muted,false));body=col();root.addView(body,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=row();for(String x:new String[]{"VISUAL LAB","BENCHMARK","ALGORITHM GUIDE"}){Button b=button(x);nav.addView(b,new LinearLayout.LayoutParams(0,d(58),1));if(x.startsWith("VISUAL"))b.setOnClickListener(v->showLab());else if(x.startsWith("BENCH"))b.setOnClickListener(v->showBenchmark());else b.setOnClickListener(v->showGuide());}root.addView(nav);setContentView(root);}
 void showLab(){body.removeAllViews();ScrollView scroll=new ScrollView(this);LinearLayout box=col();scroll.addView(box);box.addView(section("PATHFINDING PLAYGROUND","Choose endpoints, zoom the universe and inspect why the engine selected its result."));LinearLayout choose=row();Button s=outline("SELECT START: "+start),g=outline("SELECT END: "+goal);choose.addView(s,new LinearLayout.LayoutParams(0,d(48),1));choose.addView(g,new LinearLayout.LayoutParams(0,d(48),1));box.addView(choose);universe=new UniverseView(this);box.addView(universe,new LinearLayout.LayoutParams(-1,d(390)));algorithm=new Spinner(this);algorithm.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,Algorithms.NAMES));box.addView(algorithm,new LinearLayout.LayoutParams(-1,d(52)));Button run=button("RUN & EXPLAIN");box.addView(run,new LinearLayout.LayoutParams(-1,d(54)));status=txt("Green = start  •  Red = end  •  Yellow = solution\nPinch to zoom. Drag to pan. Choose START or END, then tap a dot.",14,Color.WHITE,false);status.setBackground(card());box.addView(status);s.setOnClickListener(v->{choosingStart=true;status.setText("Tap a dot to set START");});g.setOnClickListener(v->{choosingStart=false;status.setText("Tap a dot to set END");});run.setOnClickListener(v->runSelected());body.addView(scroll,new LinearLayout.LayoutParams(-1,-1));}
 void runSelected(){String n=(String)algorithm.getSelectedItem();Algorithms.Result r=Algorithms.run(n,graph,start,goal);universe.solution=r.path();universe.invalidate();AlgorithmInfo.Info i=AlgorithmInfo.get(n);status.setText(n+"\nCost: "+r.cost()+"  |  Operations: "+r.visited()+"  |  Compute: "+String.format(Locale.US,"%.3f ms",r.nanos()/1e6)+"\n\nWHY THIS RESULT\n"+r.note()+"\n\nTime: "+i.time()+"  |  Space: "+i.space()+"\nBest for: "+i.bestFor());}
 void showBenchmark(){body.removeAllViews();LinearLayout w=col();w.addView(section("CONTROLLED BENCHMARK","3 warm-ups + 10 measured runs. Rendering excluded; median reduces timing noise."));Button run=button("RUN ALL 10 ALGORITHMS");w.addView(run,new LinearLayout.LayoutParams(-1,d(54)));TextView sum=txt("Ready • Nodes "+graph.size()+" • Edges "+graph.edges.size()+" • "+start+" → "+goal,13,muted,false);w.addView(sum);HorizontalScrollView hs=new HorizontalScrollView(this);TableLayout table=new TableLayout(this);hs.addView(table);ScrollView vs=new ScrollView(this);vs.addView(hs);w.addView(vs,new LinearLayout.LayoutParams(-1,0,1));header(table);run.setOnClickListener(v->{run.setEnabled(false);sum.setText("Benchmark running…");table.removeViews(1,Math.max(0,table.getChildCount()-1));new Thread(()->{ArrayList<String[]> rows=new ArrayList<>();for(String n:Algorithms.NAMES){for(int q=0;q<3;q++)Algorithms.run(n,graph,start,goal);long[] ts=new long[10];Algorithms.Result last=null;for(int j=0;j<10;j++){last=Algorithms.run(n,graph,start,goal);ts[j]=last.nanos();}Arrays.sort(ts);AlgorithmInfo.Info i=AlgorithmInfo.get(n);rows.add(new String[]{n,String.format(Locale.US,"%.3f",ts[5]/1e6),""+last.cost(),""+last.visited(),""+last.path().size(),i.time(),i.space(),last.path().isEmpty()?"N/A":"PASS"});}runOnUiThread(()->{int rank=1;for(String[] a:rows)addRow(table,rank++,a);sum.setText("Complete • Results are device-specific");run.setEnabled(true);});}).start();});body.addView(w,new LinearLayout.LayoutParams(-1,-1));}
 void header(TableLayout t){TableRow r=new TableRow(this);for(String x:new String[]{"#","Algorithm","Median ms","Cost","Ops","Path","Time complexity","Space","Valid"})r.addView(cell(x,true));t.addView(r);}void addRow(TableLayout t,int rank,String[] a){TableRow r=new TableRow(this);r.setBackgroundColor(rank%2==0?Color.rgb(12,28,48):Color.rgb(8,19,34));r.addView(cell(""+rank,false));for(String x:a)r.addView(cell(x,false));t.addView(r);}
 void showGuide(){body.removeAllViews();LinearLayout out=col();out.addView(section("ALGORITHM KNOWLEDGE TABLE","Functional meaning plus technical trade-offs, complexity, output cost, strengths and limitations."));ScrollView sv=new ScrollView(this);LinearLayout list=col();sv.addView(list);int k=1;for(AlgorithmInfo.Info i:AlgorithmInfo.ALL){LinearLayout c=col();c.setPadding(d(14),d(12),d(14),d(12));c.setBackground(card());c.addView(txt(k+++". "+i.name(),18,cyan,true));c.addView(kv("FUNCTIONAL",i.functional()));c.addView(kv("TECHNICAL",i.purpose()));c.addView(kv("TIME",i.time()));c.addView(kv("SPACE",i.space()));c.addView(kv("OPTIMALITY",i.optimal()));c.addView(kv("COST / OUTPUT",i.name().contains("MST")?"Minimum total spanning cost":"Depends on graph weights and selected endpoints"));c.addView(kv("PROS",i.pros()));c.addView(kv("CONS",i.cons()));c.addView(kv("BEST FOR",i.bestFor()));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(d(10),d(5),d(10),d(8));list.addView(c,p);}out.addView(sv,new LinearLayout.LayoutParams(-1,0,1));body.addView(out,new LinearLayout.LayoutParams(-1,-1));}
 TextView kv(String k,String v){TextView x=txt(k+"  •  "+v,13,Color.WHITE,false);x.setPadding(0,d(3),0,d(3));return x;}TextView section(String h,String s){TextView t=txt(h+"\n"+s,15,Color.WHITE,true);t.setPadding(d(14),d(10),d(14),d(10));t.setBackgroundColor(panel);return t;}TextView cell(String s,boolean h){TextView v=txt(s,12,h?bg:Color.WHITE,h);v.setPadding(d(10),d(9),d(10),d(9));if(h)v.setBackgroundColor(cyan);v.setMinWidth(d(s.contains("complex")?150:s.equals("Algorithm")?170:70));return v;}
 LinearLayout col(){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);return x;}LinearLayout row(){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.HORIZONTAL);return x;}TextView txt(String s,int z,int c,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextColor(c);v.setTextSize(z);v.setPadding(d(14),d(6),d(14),d(6));if(bold)v.setTypeface(Typeface.DEFAULT_BOLD);return v;}Button button(String s){Button b=new Button(this);b.setText(s);b.setTextColor(bg);b.setTextSize(11);b.setTypeface(Typeface.DEFAULT_BOLD);GradientDrawable g=new GradientDrawable();g.setColor(cyan);g.setCornerRadius(d(10));g.setStroke(d(3),bg);b.setBackground(g);return b;}Button outline(String s){Button b=button(s);b.setTextColor(cyan);b.setBackground(card());return b;}GradientDrawable card(){GradientDrawable g=new GradientDrawable();g.setColor(panel);g.setCornerRadius(d(12));g.setStroke(d(1),Color.rgb(45,73,103));return g;}int d(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 final class UniverseView extends View{Paint p=new Paint(3);List<Integer> solution=List.of();float scale=1,ox=0,oy=0,lx,ly;boolean drag;ScaleGestureDetector zoom;UniverseView(Context c){super(c);zoom=new ScaleGestureDetector(c,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector s){scale=Math.max(1,Math.min(3.5f,scale*s.getScaleFactor()));invalidate();return true;}});setContentDescription("Interactive graph. Tap nodes to select endpoints.");}protected void onDraw(Canvas c){super.onDraw(c);c.drawColor(bg);c.save();c.translate(ox,oy);c.scale(scale,scale);float w=getWidth()/scale,h=getHeight()/scale;p.setStrokeWidth(d(1)/scale);p.setColor(Color.rgb(37,64,94));for(Graph.Edge e:graph.edges){Graph.Node a=graph.nodes.get(e.from()),b=graph.nodes.get(e.to());c.drawLine(a.x()*w,a.y()*h,b.x()*w,b.y()*h,p);}p.setStrokeWidth(d(5)/scale);p.setColor(yellow);for(int i=1;i<solution.size();i++){Graph.Node a=graph.nodes.get(solution.get(i-1)),b=graph.nodes.get(solution.get(i));c.drawLine(a.x()*w,a.y()*h,b.x()*w,b.y()*h,p);}for(Graph.Node n:graph.nodes){p.setColor(n.id()==start?Color.rgb(86,255,111):n.id()==goal?Color.rgb(255,74,92):solution.contains(n.id())?yellow:Color.rgb(137,165,255));c.drawCircle(n.x()*w,n.y()*h,d(8)/scale,p);p.setTextSize(d(10)/scale);p.setColor(Color.WHITE);c.drawText(""+n.id(),n.x()*w+d(10)/scale,n.y()*h-d(7)/scale,p);}c.restore();}public boolean onTouchEvent(android.view.MotionEvent e){zoom.onTouchEvent(e);if(e.getAction()==0){lx=e.getX();ly=e.getY();drag=false;return true;}if(e.getAction()==2&&!zoom.isInProgress()){float dx=e.getX()-lx,dy=e.getY()-ly;if(Math.abs(dx)+Math.abs(dy)>6)drag=true;ox+=dx;oy+=dy;lx=e.getX();ly=e.getY();invalidate();return true;}if(e.getAction()==1&&!drag){float x=(e.getX()-ox)/scale,y=(e.getY()-oy)/scale;int id=nearest(x,y);if(choosingStart){start=id;status.setText("Start = "+id+". Choose END or run.");}else{goal=id;status.setText("End = "+id+". Select an algorithm and run.");}solution=List.of();invalidate();return true;}return true;}int nearest(float x,float y){float w=getWidth()/scale,h=getHeight()/scale,b=Float.MAX_VALUE;int id=0;for(Graph.Node n:graph.nodes){float dx=x-n.x()*w,dy=y-n.y()*h,z=dx*dx+dy*dy;if(z<b){b=z;id=n.id();}}return id;}}
}
